namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Drizzle with olive oil and season with salt.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and serve immediately."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and cumin for at least 1 hour.",
                    "Grill or broil chicken until lightly charred, then cut into pieces.",
                    "Sauté onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in heavy cream and add the cooked chicken.",
                    "Simmer for 10 more minutes. Serve with basmati rice or naan."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                Ratings = [4, 4, 3, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A rich Roman pasta dish with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente. Reserve 1 cup pasta water.",
                    "Cook pancetta in a skillet until crispy.",
                    "Whisk eggs and grated Pecorino together in a bowl.",
                    "Toss hot drained pasta with pancetta and remove from heat.",
                    "Quickly stir in the egg mixture, tossing constantly. Add pasta water as needed.",
                    "Season generously with black pepper and serve immediately."
                ],
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and a tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes; drain.",
                    "Mix tamarind paste, fish sauce, and sugar to make the sauce.",
                    "Stir-fry shrimp in oil until pink; set aside.",
                    "Scramble eggs in the same pan.",
                    "Add noodles and sauce; toss until noodles are tender.",
                    "Return shrimp, add bean sprouts and green onions. Toss to combine.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh, chunky avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and chopped cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Soup", Category = "Japanese",
                Description = "A warm, savory soup with tofu, seaweed, and miso paste.",
                Ingredients = ["Dashi stock", "Miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = [
                    "Bring dashi stock to a gentle simmer.",
                    "Rehydrate wakame in water for 5 minutes; drain.",
                    "Cut tofu into small cubes.",
                    "Dissolve miso paste in a ladle of warm dashi, then stir into the pot.",
                    "Add tofu and wakame. Heat gently — do not boil.",
                    "Serve in bowls garnished with sliced green onions."
                ],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Crispy on the edges, chewy in the middle — the classic cookie.",
                Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "Flour", "Baking soda", "Salt", "Chocolate chips"],
                Steps = [
                    "Preheat oven to 375°F (190°C).",
                    "Cream butter with both sugars until light and fluffy.",
                    "Beat in eggs and vanilla.",
                    "Whisk flour, baking soda, and salt; gradually mix into wet ingredients.",
                    "Fold in chocolate chips.",
                    "Drop rounded tablespoons onto baking sheets.",
                    "Bake for 9–11 minutes until golden. Cool on the pan for 5 minutes."
                ],
                Ratings = [5, 5, 5, 5, 4]
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

