@page "/category/{CategoryName}"
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">
                            <a href="recipe/@recipe.Id">@recipe.Title</a>
                        </h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <span class="text-muted ms-1">(@recipe.AverageRating)</span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(Uri.UnescapeDataString(CategoryName));
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService Recipes

@if (recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Uri.EscapeDataString(recipe.Category)">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h4>📋 Steps</h4>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-2">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(RecipeId);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

@inject RecipeService Recipes

<div class="d-inline-flex align-items-center gap-2">
    <div class="star-rating" role="group" aria-label="Rate this recipe 1 to 5 stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hoverRating ?? currentRating) ? "active" : "")"
                  role="button"
                  aria-label="@star star(s)"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoverRating = star"
                  @onmouseout="() => hoverRating = null">
                @(star <= (hoverRating ?? currentRating) ? "★" : "☆")
            </span>
        }
    </div>

    @if (submitted)
    {
        <span class="badge bg-success">Thanks! You rated @currentRating star(s).</span>
    }

    @if (averageRating > 0)
    {
        <small class="text-muted">Avg: @averageRating / 5 (@totalRatings ratings)</small>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int currentRating;
    private int? hoverRating;
    private bool submitted;
    private double averageRating;
    private int totalRatings;

    protected override void OnParametersSet() => LoadRating();

    private void Rate(int stars)
    {
        currentRating = stars;
        Recipes.AddRating(RecipeId, stars);
        submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            totalRatings = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">
        @successMessage <a href="recipe/@createdId">View your recipe →</a>
    </div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => submission.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">— Select a category —</option>
            @foreach (var cat in categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients"
                       placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => submission.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                       placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Combine with wet ingredients" />
        <ValidationMessage For="() => submission.Steps" />
    </div>

    <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private IReadOnlyList<string> categories = [];
    private string? successMessage;
    private int createdId;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title)
        && !string.IsNullOrWhiteSpace(submission.Category)
        && !string.IsNullOrWhiteSpace(submission.Ingredients)
        && !string.IsNullOrWhiteSpace(submission.Steps);

    protected override void OnInitialized()
    {
        categories = Recipes.GetCategories();
    }

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var recipe = Recipes.AddRecipe(submission);
        createdId = recipe.Id;
        successMessage = $"\"{recipe.Title}\" submitted successfully!";
        submission = new();
        categories = Recipes.GetCategories();
    }
}

