@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int currentRating;
    private int? hoverRating;
    private bool submitted;
    private double averageRating;
    private int totalRatings;

    protected override void OnParametersSet() => LoadRating();

    private void Rate(int stars)
    {
        currentRating = stars;
        Recipes.AddRating(RecipeId, stars);
        submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            totalRatings = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">
        @successMessage <a href="recipe/@createdId">View your recipe →</a>
    </div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => submission.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">— Select a category —</option>
            @foreach (var cat in categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients"
                       placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => submission.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                       placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Combine with wet ingredients" />
        <ValidationMessage For="() => submission.Steps" />
    </div>

    <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private IReadOnlyList<string> categories = [];
    private string? successMessage;
    private int createdId;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title)
        && !string.IsNullOrWhiteSpace(submission.Category)
        && !string.IsNullOrWhiteSpace(submission.Ingredients)
        && !string.IsNullOrWhiteSpace(submission.Steps);

    protected override void OnInitialized()
    {
        categories = Recipes.GetCategories();
    }

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var recipe = Recipes.AddRecipe(submission);
        createdId = recipe.Id;
        successMessage = $"\"{recipe.Title}\" submitted successfully!";
        submission = new();
        categories = Recipes.GetCategories();
    }
}

