+@rendermode InteractiveServer
+@using RecipeHub.Services
+
+@inject RecipeService Recipes
+
+<div class="d-inline-flex align-items-center gap-2">
+    <div class="star-rating" role="group" aria-label="Rate this recipe 1 to 5 stars">
+        @for (int i = 1; i <= 5; i++)
+        {
+            var star = i;
+            <span class="star @(star <= (hoverRating ?? currentRating) ? "active" : "")"
+                  role="button"
+                  aria-label="@star star(s)"
+                  @onclick="() => Rate(star)"
+                  @onmouseover="() => hoverRating = star"
+                  @onmouseout="() => hoverRating = null">
+                @(star <= (hoverRating ?? currentRating) ? "★" : "☆")
+            </span>
+        }
+    </div>
+
+    @if (submitted)
+    {
+        <span class="badge bg-success">Thanks! You rated @currentRating star(s).</span>
+    }
+
+    @if (averageRating > 0)
+    {
+        <small class="text-muted">Avg: @averageRating / 5 (@totalRatings ratings)</small>
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired]
+    public int RecipeId { get; set; }
+
+    private int currentRating;
+    private int? hoverRating;
+    private bool submitted;
+    private double averageRating;
+    private int totalRatings;
+
+    protected override void OnParametersSet() => LoadRating();
+
+    private void Rate(int stars)
+    {
+        currentRating = stars;
+        Recipes.AddRating(RecipeId, stars);
+        submitted = true;
+        LoadRating();
+    }
+
+    private void LoadRating()
+    {
+        var recipe = Recipes.GetById(RecipeId);
+        if (recipe is not null)
+        {
+            averageRating = recipe.AverageRating;
+            totalRatings = recipe.Ratings.Count;
+        }
+    }
+}
